package kr.tong.sky;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.nio.file.*;import java.util.*;import java.time.*;import java.security.*;import java.nio.charset.StandardCharsets;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=35,packageName="kr.tong.sky")
public class TripSearchTest {
 JSONObject catalog()throws Exception{return new JSONObject(Files.readString(Path.of(System.getProperty("tongsky.assets"),"regions.json")));}
 JSONArray read(String name)throws Exception{try(var in=getClass().getResourceAsStream("/"+name)){return new JSONArray(new String(in.readAllBytes(),StandardCharsets.UTF_8));}}
 @Test public void everyRealSavedCombinationMatchesWebsiteAcrossAllRegionsAndDurations()throws Exception{
  JSONArray source=read("parity.json"),expected=read("trip-expected.json");List<TripSearch.Snapshot> raw=new ArrayList<>();for(int i=0;i<source.length();i++){JSONObject record=source.getJSONObject(i).getJSONObject("raw");raw.add(new TripSearch.Snapshot(record,record.getLong("success")));}
  String before=source.toString();TripSearch.Dataset data=TripSearch.prepare(raw,catalog(),"ICN",false);assertEquals(before,source.toString());int total=0;
  for(int i=0;i<expected.length();i++){JSONObject q=expected.getJSONObject(i);TripSearch.Result result=TripSearch.find(data,q.getString("region"),q.getInt("days"),LocalDate.parse("2026-11-03"),LocalDate.parse("2027-10-28"));for(int type=0;type<3;type++){JSONObject e=q.getJSONArray("groups").getJSONObject(type);TripSearch.Group group=result.groups[type];assertEquals(q.toString(),e.getInt("count"),group.total);MessageDigest digest=MessageDigest.getInstance("SHA-256");int same=0,cross=0;for(int n=0;n<group.total;n++){TripSearch.Match m=group.get(n);digest.update((m.out.date+"|"+m.out.code+"|"+m.back.date+"|"+m.back.code+"\n").getBytes(StandardCharsets.UTF_8));if(m.out.code.equals(m.back.code))same++;else cross++;assertEquals(q.getInt("days")-1,java.time.temporal.ChronoUnit.DAYS.between(LocalDate.parse(m.out.date),LocalDate.parse(m.back.date)));}assertEquals(q.toString(),e.getString("sha256"),HexFormat.of().formatHex(digest.digest()));assertEquals(e.getInt("same"),same);assertEquals(e.getInt("cross"),cross);total+=group.total;}}
  assertEquals(23573,total);System.out.println("TRIP_PARITY_PASS: "+expected.length()+" searches / "+total+" exact combinations, all three categories");
 }
 JSONObject month(String a,String b,boolean oz)throws Exception{JSONObject m=new JSONObject().put("carrier",oz?"OZ":"KE").put("origin",a).put("destination",b).put("month","2026-11").put("sourceUpdatedAt","2026-11-02T23:00:00+09:00").put("collectedAt","2026-11-03T00:00:00+09:00");JSONArray ds=new JSONArray();for(int i=1;i<=30;i++){JSONObject d=new JSONObject().put("date",String.format(Locale.ROOT,"2026-11-%02d",i)).put("status","OBSERVED");for(String f:Search.ALL_FIELDS)d.put(f,false);ds.put(d);}return m.put("dates",ds);}
 @Test public void asianaKeepsBothDirectionsAndSupportsSameCityAndOpenJawWithoutMixingRegions()throws Exception{
  JSONObject cat=new JSONObject("{\"regions\":{\"유럽\":[{\"code\":\"CDG\",\"name\":\"파리\"},{\"code\":\"LHR\",\"name\":\"런던\"}],\"미주\":[{\"code\":\"JFK\"}]}}");List<TripSearch.Snapshot> input=new ArrayList<>();for(String city:List.of("CDG","LHR","JFK"))for(boolean out:new boolean[]{true,false}){JSONObject m=month(out?"ICN":city,out?city:"ICN",true);JSONObject d=m.getJSONArray("dates").getJSONObject(out?9:15);d.put("prestigeAward",true).put("prestigeUpgrade",true);input.add(new TripSearch.Snapshot(m,1));}TripSearch.Result r=TripSearch.find(TripSearch.prepare(input,cat,"ICN",true),"유럽",7,LocalDate.parse("2026-11-03"),LocalDate.parse("2027-10-28"));for(TripSearch.Group g:r.groups){assertEquals(4,g.total);assertEquals("CDG",g.get(0).out.code);assertEquals("CDG",g.get(0).back.code);assertEquals("CDG",g.get(1).out.code);assertEquals("LHR",g.get(1).back.code);}assertEquals(3,r.groups.length);
 }
 @Test public void unknownReviewAndExcludedDaysCannotCreateTrips()throws Exception{
  JSONObject cat=new JSONObject("{\"regions\":{\"유럽\":[{\"code\":\"CDG\"}]}}");for(String reason:List.of("UNKNOWN","NO_FLIGHT","review","excluded")){JSONObject out=month("ICN","CDG",true),back=month("CDG","ICN",true),d=out.getJSONArray("dates").getJSONObject(9);d.put("prestigeAward",true);back.getJSONArray("dates").getJSONObject(15).put("prestigeAward",true);if(reason.equals("review"))d.put("repeatMarkerReview",new JSONObject());else if(reason.equals("excluded"))d.put("repeatMarkerExclusion",new JSONObject());else d.put("status",reason);TripSearch.Dataset data=new TripSearch.Dataset(List.of(new TripSearch.Snapshot(out,1),new TripSearch.Snapshot(back,1)),cat,"ICN",true);assertEquals(reason,0,TripSearch.find(data,"유럽",7,LocalDate.parse("2026-11-03"),LocalDate.parse("2027-10-28")).total());}
 }
 @Test public void invalidInputsAndOutOfRangeIndexesAreRejected()throws Exception{TripSearch.Dataset data=new TripSearch.Dataset(List.of(),catalog(),"ICN",false);for(int days:new int[]{0,-1,361})try{TripSearch.find(data,"유럽",days,Search.today(),Search.lastDate(false));fail();}catch(IllegalArgumentException expected){}try{TripSearch.find(data,"전체",7,Search.today(),Search.lastDate(false));fail();}catch(IllegalArgumentException expected){}TripSearch.Group group=new TripSearch.Group(0);try{group.get(0);fail();}catch(IndexOutOfBoundsException expected){}}
}
